"use client";

import { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  DragOverlay,
  PointerSensor,
  closestCenter,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import { SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";
import {
import {
  ArrowLeft,
  Download,
  Monitor,
  Redo2,
  Save,
  Smartphone,
  Tablet,
  Undo2,
  UploadCloud,
  FileText
} from "lucide-react";
import Link from "next/link";
import { toast } from "sonner";
import { COMPONENT_PALETTE } from "@/features/builder/componentRegistry";
import { SectionRenderer } from "@/features/builder/SectionRenderer";
import { updateProjectCanvas, createPage } from "@/actions/projects";
import { publishProject } from "@/actions/publish";
import { ThemeToggle } from "@/components/layout/ThemeToggle";
import { AiBuilderPanel } from "@/components/builder/AiBuilderPanel";
import { BuilderInspector } from "@/components/builder/BuilderInspector";
import { CanvasEndDrop } from "@/components/builder/CanvasEndDrop";
import { PaletteItem } from "@/components/builder/PaletteItem";
import { SortableSection } from "@/components/builder/SortableSection";
import { Button } from "@/components/ui/Button";
import {
  addSection,
  hydrateFromServer,
  insertSectionAt,
  markSaved,
  redo,
  reorderSections,
  selectSection,
  setViewport,
  undo,
} from "@/redux/slices/builderSlice";
import { useAppDispatch, useAppSelector } from "@/hooks/useRedux";
import { cn } from "@/utils/cn";
import { exportPageHtml } from "@/utils/exportCode";

export function BuilderClient({ project }) {
  const dispatch = useAppDispatch();
  const document = useAppSelector((s) => s.builder.document);
  const viewport = useAppSelector((s) => s.builder.viewport);
  const selectedId = useAppSelector((s) => s.builder.selectedSectionId);
  const isDirty = useAppSelector((s) => s.builder.isDirty);
  const [saving, setSaving] = useState(false);
  const [publishing, setPublishing] = useState(false);
  const [aiBusy, setAiBusy] = useState(false);
  const [activeDrag, setActiveDrag] = useState(null);

  const [pages, setPages] = useState(project.pages || []);
  const [activePageId, setActivePageId] = useState(project.pages?.[0]?.id || null);

  useEffect(() => {
    const activePage = pages.find(p => p.id === activePageId) || pages[0];
    dispatch(
      hydrateFromServer({
        projectId: project.id,
        projectName: project.name,
        viewport: project.viewport || "desktop",
        canvasData: activePage ? activePage.canvasData : project.canvasData,
      }),
    );
  }, [dispatch, project.id, project.name, project.viewport, activePageId, project.canvasData]);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 8 },
    }),
  );

  const sectionIds = useMemo(() => document.sections.map((s) => s.id), [document.sections]);

  async function handleSave(showAlert = true) {
    setSaving(true);
    try {
      // Update local pages array so switching back shows saved data
      setPages(prev => prev.map(p => p.id === activePageId ? { ...p, canvasData: document } : p));
      const res = await updateProjectCanvas(project.id, document, viewport, activePageId);
      if (!res.ok) throw new Error(res.error || "Save failed");
      dispatch(markSaved());
      if (showAlert) toast.success("Page saved");
    } catch (e) {
      if (showAlert) toast.error(e instanceof Error ? e.message : "Save failed");
    } finally {
      setSaving(false);
    }
  }

  async function handlePageSwitch(newId) {
    if (newId === "new") {
      const title = window.prompt("New page title (e.g. About):");
      if (!title) return;
      handleSave(false); // auto-save current
      const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, "-");
      const res = await createPage(project.id, title, slug);
      if (res.ok) {
        setPages([...pages, res.page]);
        setActivePageId(res.page.id);
        toast.success("Page created");
      } else {
        toast.error("Failed to create page");
      }
      return;
    }
    await handleSave(false);
    setActivePageId(newId);
  }

  async function handlePublish() {
    setPublishing(true);
    try {
      await handleSave();
      const res = await publishProject(project.id, project.slug);
      if (!res.ok) throw new Error(res.error || "Publish failed");
      const url = `${window.location.origin}/p/${res.published.subdomain}`;
      toast.success("Published", { description: url });
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Publish failed");
    } finally {
      setPublishing(false);
    }
  }

  function handleExport() {
    const html = exportPageHtml(document, { title: project.name });
    const blob = new Blob([html], { type: "text/html" });
    const url = URL.createObjectURL(blob);
    const a = window.document.createElement("a");
    a.href = url;
    const activePageTitle = pages.find(p => p.id === activePageId)?.slug || "index";
    a.download = `${project.slug || "nexora-site"}-${activePageTitle}.html`;
    a.click();
    URL.revokeObjectURL(url);
    toast.success("HTML exported");
  }

  function onDragStart(event) {
    const { active } = event;
    if (active.data.current?.fromPalette) {
      setActiveDrag({ kind: "palette", type: active.data.current.type });
    } else {
      const sec = document.sections.find((s) => s.id === active.id);
      setActiveDrag({ kind: "sort", section: sec });
    }
  }

  function onDragEnd(event) {
    const { active, over } = event;
    setActiveDrag(null);
    if (!over) return;

    if (active.data.current?.fromPalette) {
      const type = active.data.current.type;
      if (String(over.id) === "canvas-end") {
        dispatch(addSection({ type }));
        return;
      }
      const overIndex = document.sections.findIndex((s) => s.id === over.id);
      if (overIndex >= 0) {
        dispatch(insertSectionAt({ index: overIndex, type }));
      }
      return;
    }

    if (active.id !== over.id) {
      dispatch(reorderSections({ activeId: active.id, overId: over.id }));
    }
  }

  const previewWidth =
    viewport === "mobile" ? "min-w-[320px] max-w-[390px]" : viewport === "tablet" ? "max-w-[768px]" : "max-w-5xl";

  return (
    <div className="flex h-[100dvh] flex-col bg-[var(--background)] text-[var(--foreground)]">
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--border)] bg-[var(--card)] px-4 py-3">
        <div className="flex min-w-[200px] items-center gap-3">
          <Link
            href="/dashboard"
            aria-label="Back to dashboard"
            className="inline-flex size-9 items-center justify-center rounded-lg border border-transparent text-[var(--foreground)] hover:bg-[var(--muted)]"
          >
            <ArrowLeft className="size-4" />
          </Link>
          <div className="hidden sm:block">
            <div className="text-[10px] uppercase tracking-wide text-[var(--muted-foreground)]">
              Project
            </div>
            <div className="flex items-center gap-2">
              <span className="font-display text-sm font-semibold">{project.name}</span>
              <Link
                href={`/dashboard/projects/${project.id}/settings`}
                className="text-[10px] font-medium text-[var(--accent)] hover:underline"
              >
                Settings
              </Link>
            </div>
          </div>
          <div className="h-6 w-[1px] bg-[var(--border)] hidden lg:block mx-1"></div>

          <div className="flex items-center gap-2">
            <FileText className="size-4 text-[var(--muted-foreground)]" />
            <select 
              value={activePageId || ""}
              onChange={(e) => handlePageSwitch(e.target.value)}
              className="bg-transparent text-sm font-medium outline-none cursor-pointer border border-transparent hover:border-[var(--border)] rounded px-1 py-0.5 transition-colors"
            >
              {pages.map(p => <option key={p.id} value={p.id} className="bg-[var(--background)] text-[var(--foreground)]">{p.title || p.slug}</option>)}
              <option value="new" className="bg-[var(--background)] text-[var(--foreground)]">+ New Page</option>
            </select>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <div className="mr-1 flex items-center rounded-xl border border-[var(--border)] p-1">
            <Button
              type="button"
              variant={viewport === "desktop" ? "primary" : "ghost"}
              size="sm"
              className="px-2"
              onClick={() => dispatch(setViewport("desktop"))}
              aria-label="Desktop preview"
            >
              <Monitor className="size-4" />
            </Button>
            <Button
              type="button"
              variant={viewport === "tablet" ? "primary" : "ghost"}
              size="sm"
              className="px-2"
              onClick={() => dispatch(setViewport("tablet"))}
              aria-label="Tablet preview"
            >
              <Tablet className="size-4" />
            </Button>
            <Button
              type="button"
              variant={viewport === "mobile" ? "primary" : "ghost"}
              size="sm"
              className="px-2"
              onClick={() => dispatch(setViewport("mobile"))}
              aria-label="Mobile preview"
            >
              <Smartphone className="size-4" />
            </Button>
          </div>
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={() => dispatch(undo())}
            aria-label="Undo"
          >
            <Undo2 className="size-4" />
          </Button>
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={() => dispatch(redo())}
            aria-label="Redo"
          >
            <Redo2 className="size-4" />
          </Button>
          <ThemeToggle />
          <Button
            type="button"
            variant="secondary"
            size="sm"
            onClick={handleExport}
            disabled={aiBusy}
          >
            <Download className="mr-1 size-4" />
            Export
          </Button>
          <Button
            type="button"
            variant="secondary"
            size="sm"
            onClick={handleSave}
            disabled={saving || !isDirty}
          >
            <Save className="mr-1 size-4" />
            {saving ? "Saving…" : "Save"}
          </Button>
          <Button type="button" size="sm" onClick={handlePublish} disabled={publishing || aiBusy}>
            <UploadCloud className="mr-1 size-4" />
            {publishing ? "Publishing…" : "Publish"}
          </Button>
        </div>
      </header>

      <div className="flex min-h-0 flex-1">
        <aside className="hidden w-72 shrink-0 flex-col border-r border-[var(--border)] bg-[var(--card)] lg:flex">
          <div className="border-b border-[var(--border)] p-4 font-display text-sm font-semibold">
            Components
          </div>
          <div className="flex-1 space-y-2 overflow-y-auto p-3">
            {COMPONENT_PALETTE.map((c) => (
              <div key={c.type} className="space-y-1">
                <PaletteItem type={c.type} label={c.label} />
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  className="h-7 w-full text-[10px] text-[var(--muted-foreground)]"
                  onClick={() => dispatch(addSection({ type: c.type }))}
                >
                  + Add {c.label}
                </Button>
              </div>
            ))}
          </div>
          <div className="border-t border-[var(--border)] p-3">
            <AiBuilderPanel onBusyChange={setAiBusy} />
          </div>
        </aside>

        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragStart={onDragStart}
          onDragEnd={onDragEnd}
          onDragCancel={() => setActiveDrag(null)}
        >
          <main
            className="min-h-0 flex-1 overflow-y-auto builder-canvas"
            onClick={() => dispatch(selectSection(null))}
          >
            <div className="mx-auto w-full px-4 py-6 transition-all">
              <div className={cn("mx-auto w-full", previewWidth)}>
                <SortableContext items={sectionIds} strategy={verticalListSortingStrategy}>
                  <div className="flex flex-col gap-4">
                    {document.sections.map((section) => (
                      <div
                        key={section.id}
                        onClick={(e) => {
                          e.stopPropagation();
                          dispatch(selectSection(section.id));
                        }}
                      >
                        <SortableSection
                          section={section}
                          selected={selectedId === section.id}
                          isEditor
                          onSelect={(id) => dispatch(selectSection(id))}
                        />
                      </div>
                    ))}
                    <CanvasEndDrop />
                  </div>
                </SortableContext>
              </div>
            </div>
          </main>

          <DragOverlay dropAnimation={null}>
            {activeDrag?.kind === "palette" ? (
              <div className="rounded-xl border border-[var(--accent)] bg-[var(--card)] px-3 py-2 text-sm shadow-lg">
                {COMPONENT_PALETTE.find((c) => c.type === activeDrag.type)?.label}
              </div>
            ) : activeDrag?.kind === "sort" && activeDrag.section ? (
              <div className="opacity-90">
                <SectionRenderer section={activeDrag.section} />
              </div>
            ) : null}
          </DragOverlay>
        </DndContext>

        <aside className="hidden w-[340px] shrink-0 border-l border-[var(--border)] bg-[var(--card)] xl:block">
          <BuilderInspector />
        </aside>
      </div>

      {isDirty ? (
        <div className="border-t border-[var(--border)] bg-amber-500/10 px-4 py-2 text-center text-xs text-amber-800 dark:text-amber-200">
          Unsaved changes — remember to save before publishing.
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useState } from "react";
import { cn } from "@/utils/cn";
import { Menu, X, ChevronDown, ChevronUp } from "lucide-react";

function sectionShell({ section, children, className }) {
  const s = section.style || {};
  const py = Number(s.paddingY) || 0;
  const px = Number(s.paddingX) || 0;
  const maxWidth = Number(s.maxWidth) || 1200;
  return (
    <section
      className={cn("relative w-full", className)}
      style={{
        background: s.background || "transparent",
        color: s.textColor || "inherit",
        paddingTop: py,
        paddingBottom: py,
        paddingLeft: px,
        paddingRight: px,
      }}
    >
      <div className="mx-auto w-full" style={{ maxWidth }}>
        {children}
      </div>
    </section>
  );
}

function InteractiveNavbar({ props, commonProps, isEditor }) {
  const [isOpen, setIsOpen] = useState(false);
  const links = String(props.links || "").split(",").map((l) => l.trim()).filter(Boolean);

  return (
    <header
      {...commonProps}
      className={cn(
        "flex flex-wrap items-center justify-between gap-4",
        props.sticky && "sticky top-0 z-10 backdrop-blur bg-black/10 transition-colors"
      )}
    >
      <span className="font-display text-lg font-semibold tracking-tight">
        {props.brand}
      </span>

      {/* Desktop Nav */}
      <nav className="hidden md:flex flex-wrap items-center gap-4 text-sm opacity-90">
        {links.map((l) => (
          <a key={l} href="#" className="hover:opacity-100 transition-opacity" onClick={(e) => isEditor && e.preventDefault()}>{l}</a>
        ))}
      </nav>
      <div className="hidden md:block">
        <button className="rounded-full bg-[var(--accent)] px-4 py-2 text-xs font-semibold text-[var(--accent-foreground)] hover:brightness-110 transition-all">
          {props.cta}
        </button>
      </div>

      {/* Mobile Toggle */}
      <div className="md:hidden flex items-center">
        <button onClick={() => !isEditor && setIsOpen(!isOpen)} className="p-2">
          {isOpen ? <X className="size-5" /> : <Menu className="size-5" />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isOpen && !isEditor && (
        <div className="w-full basis-full mt-4 flex flex-col gap-3 md:hidden">
          {links.map((l) => (
            <a key={l} href="#" className="text-sm opacity-90 py-1 border-b border-white/10">{l}</a>
          ))}
          <button className="w-full mt-2 rounded-full bg-[var(--accent)] px-4 py-2 text-xs font-semibold text-[var(--accent-foreground)]">
            {props.cta}
          </button>
        </div>
      )}
    </header>
  );
}

function InteractiveContactForm({ props, commonProps, isEditor }) {
  const [status, setStatus] = useState("idle");

  const handleSubmit = (e) => {
    e.preventDefault();
    if (isEditor) return;
    setStatus("loading");
    setTimeout(() => {
      setStatus("success");
      setTimeout(() => setStatus("idle"), 3000);
    }, 1000);
  };

  return (
    <div {...commonProps}>
      <h3 className="font-display text-2xl font-semibold">{props.heading}</h3>
      <p className="mt-2 text-sm opacity-80">{props.subheading}</p>
      <form className="mt-6 grid gap-3 max-w-md" onSubmit={handleSubmit}>
        <input
          required
          className="rounded-lg border border-white/15 bg-black/20 px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-[var(--accent)] transition-all"
          placeholder="Name"
          disabled={status === "loading" || status === "success"}
        />
        <input
          required
          className="rounded-lg border border-white/15 bg-black/20 px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-[var(--accent)] transition-all"
          placeholder="Email"
          type="email"
          disabled={status === "loading" || status === "success"}
        />
        <textarea
          required
          className="min-h-[100px] rounded-lg border border-white/15 bg-black/20 px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-[var(--accent)] transition-all"
          placeholder="Message"
          disabled={status === "loading" || status === "success"}
        />
        <button
          type="submit"
          disabled={status === "loading" || status === "success"}
          className={cn(
            "rounded-full bg-[var(--accent)] px-4 py-2 text-sm font-semibold text-[var(--accent-foreground)] transition-all hover:brightness-110",
            status === "success" && "bg-green-600 text-white"
          )}
        >
          {status === "loading" ? "Sending..." : status === "success" ? "Sent!" : props.submitLabel}
        </button>
      </form>
    </div>
  );
}

function InteractiveFaq({ props, commonProps, isEditor }) {
  const [openIndex, setOpenIndex] = useState(null);

  const toggle = (i) => {
    if (isEditor) return;
    setOpenIndex(openIndex === i ? null : i);
  };

  return (
    <div {...commonProps}>
      <h3 className="font-display text-2xl font-semibold">{props.heading}</h3>
      <dl className="mt-6 space-y-4">
        {(props.items || []).map((item, i) => {
          const isOpen = openIndex === i;
          return (
            <div key={i} className="rounded-xl border border-white/10 bg-white/5 overflow-hidden transition-all">
              <dt 
                className={cn("font-medium p-4 flex justify-between items-center", !isEditor && "cursor-pointer hover:bg-white/5")} 
                onClick={() => toggle(i)}
              >
                <span>{item.q}</span>
                {!isEditor && (isOpen ? <ChevronUp className="size-4 opacity-50" /> : <ChevronDown className="size-4 opacity-50" />)}
              </dt>
              { (isOpen || isEditor) && (
                <dd className="px-4 pb-4 mt-1 text-sm opacity-80 border-t border-white/5 pt-3">
                  {item.a}
                </dd>
              )}
            </div>
          );
        })}
      </dl>
    </div>
  );
}

export function SectionRenderer({ section, isEditor, onSelect }) {
  const { type, props } = section;

  const wrap = (inner, extraClass) =>
    sectionShell({
      section,
      className: cn(
        extraClass,
        isEditor && "ring-1 ring-transparent hover:ring-[var(--accent)]/40 transition-shadow cursor-pointer",
      ),
      children: inner,
    });

  const commonProps = isEditor
    ? {
        role: "button",
        tabIndex: 0,
        onClick: (e) => {
          e.stopPropagation();
          onSelect?.(section.id);
        },
        onKeyDown: (e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            onSelect?.(section.id);
          }
        },
      }
    : {};

  switch (type) {
    case "navbar":
      return wrap(<InteractiveNavbar props={props} commonProps={commonProps} isEditor={isEditor} />);

    case "hero": {
      const align =
        props.align === "left"
          ? "text-left items-start"
          : props.align === "right"
            ? "text-right items-end"
            : "text-center items-center";
      return wrap(
        <div {...commonProps} className={cn("flex flex-col gap-6", align)}>
          <h1 className="font-display text-3xl font-bold tracking-tight sm:text-4xl md:text-5xl max-w-3xl">
            {props.title}
          </h1>
          <p className="max-w-2xl text-base opacity-90 sm:text-lg">{props.subtitle}</p>
          <div className="flex flex-wrap gap-3">
            <button className="rounded-full bg-[var(--accent)] px-5 py-2.5 text-sm font-semibold text-[var(--accent-foreground)] hover:brightness-110 transition-all cursor-pointer">
              {props.primaryCta}
            </button>
            <button className="rounded-full border border-white/20 px-5 py-2.5 text-sm font-medium hover:bg-white/5 transition-all cursor-pointer">
              {props.secondaryCta}
            </button>
          </div>
        </div>,
      );
    }

    case "footer":
      return wrap(
        <footer {...commonProps} className="grid gap-8 sm:grid-cols-3 text-sm">
          <div>
            <div className="font-display font-semibold">{props.brand}</div>
            <p className="mt-2 opacity-80">{props.tagline}</p>
          </div>
          <div className="opacity-80">
            {String(props.columns || "")
              .split(",")
              .map((c) => c.trim())
              .filter(Boolean)
              .map((c) => (
                <div key={c} className="mb-1">
                  <a href="#" className="hover:underline hover:opacity-100 transition-opacity" onClick={(e) => isEditor && e.preventDefault()}>{c}</a>
                </div>
              ))}
          </div>
          <div className="opacity-60">© {new Date().getFullYear()} All rights reserved.</div>
        </footer>,
      );

    case "button":
      return wrap(
        <div {...commonProps}>
          <a
            href={props.href || "#"}
            onClick={(e) => isEditor && e.preventDefault()}
            className={cn(
              "inline-flex rounded-full px-5 py-2.5 text-sm font-semibold transition-all hover:brightness-110",
              props.variant === "outline"
                ? "border border-current hover:bg-white/5"
                : "bg-[var(--accent)] text-[var(--accent-foreground)]",
            )}
          >
            {props.label}
          </a>
        </div>,
      );

    case "card":
      return wrap(
        <article
          {...commonProps}
          className="overflow-hidden rounded-2xl border border-white/10 bg-white/5 shadow-lg backdrop-blur hover:bg-white/10 transition-colors"
        >
          {props.image ? (
            <img src={props.image} alt={props.title} className="aspect-video w-full object-cover bg-black/20" />
          ) : (
            <div className="aspect-video w-full bg-black/20" />
          )}
          <div className="p-6">
            <h3 className="font-display text-lg font-semibold">{props.title}</h3>
            <p className="mt-2 text-sm opacity-85">{props.body}</p>
          </div>
        </article>,
      );

    case "testimonials":
      return wrap(
        <div {...commonProps}>
          <h3 className="font-display text-2xl font-semibold">{props.heading}</h3>
          <div className="mt-6 grid gap-4 md:grid-cols-2">
            {(props.items || []).map((it, i) => (
              <blockquote
                key={i}
                className="rounded-2xl border border-white/10 bg-white/5 p-5 text-sm hover:border-white/20 transition-colors"
              >
                <p className="opacity-90">"{it.quote}"</p>
                <footer className="mt-3 text-xs opacity-70">
                  <span className="font-semibold text-white/90">{it.author}</span> · {it.role}
                </footer>
              </blockquote>
            ))}
          </div>
        </div>,
      );

    case "pricing":
      return wrap(
        <div {...commonProps}>
          <h3 className="font-display text-2xl font-semibold">{props.heading}</h3>
          <div className="mt-8 grid gap-4 md:grid-cols-3">
            {(props.plans || []).map((p, i) => (
              <div
                key={i}
                className="rounded-2xl border border-white/10 bg-white/5 p-6 shadow-sm hover:border-[var(--accent)] transition-colors flex flex-col"
              >
                <div className="text-sm font-medium opacity-80">{p.name}</div>
                <div className="mt-2 font-display text-3xl font-bold">{p.price}</div>
                <ul className="mt-4 text-sm opacity-75 space-y-2 flex-1">
                  {String(p.features || "").split(",").map(f => f.trim()).filter(Boolean).map((f, j) => (
                    <li key={j} className="flex items-center gap-2">
                      <span className="shrink-0 size-1.5 rounded-full bg-[var(--accent)]" />
                      {f}
                    </li>
                  ))}
                </ul>
                <button className="mt-6 w-full rounded-full bg-white/10 px-4 py-2 text-sm font-semibold hover:bg-white/20 transition-colors">
                  Choose Plan
                </button>
              </div>
            ))}
          </div>
        </div>,
      );

    case "contact-form":
      return wrap(<InteractiveContactForm props={props} commonProps={commonProps} isEditor={isEditor} />);

    case "gallery": {
      const cols = Math.min(4, Math.max(2, Number(props.columns) || 3));
      const captions = String(props.captions || "")
        .split(",")
        .map((c) => c.trim())
        .filter(Boolean);
      return wrap(
        <div {...commonProps}>
          <h3 className="font-display text-2xl font-semibold">{props.heading}</h3>
          <div
            className="mt-6 grid gap-3"
            style={{ gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))` }}
          >
            {captions.map((c, i) => (
              <figure key={i} className="group overflow-hidden rounded-xl border border-white/10 cursor-pointer relative">
                <div className="aspect-[4/3] bg-gradient-to-br from-white/10 to-white/5 group-hover:scale-105 transition-transform duration-500" />
                <figcaption className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center p-4 text-center text-sm font-medium text-white shadow-sm">
                   {c}
                </figcaption>
              </figure>
            ))}
          </div>
        </div>,
      );
    }

    case "faq":
      return wrap(<InteractiveFaq props={props} commonProps={commonProps} isEditor={isEditor} />);

    default:
      return wrap(
        <div {...commonProps} className="text-sm opacity-70 p-4 border border-dashed border-white/20 rounded-xl">
          Unknown block type: {type}
        </div>,
      );
  }
}

/**
 * Serialize builder document to a single static HTML file.
 * @param {{ version?: number, sections: unknown[] }} document
 * @param {{ title?: string }} meta
 */
export function exportPageHtml(document, meta = {}) {
  const title = meta.title || "Nexora Site";
  const blocks = Array.isArray(document?.sections) ? document.sections : [];

  const body = blocks
    .map((section) => sectionToHtml(section))
    .filter(Boolean)
    .join("\n");

  const script = `
    document.addEventListener("DOMContentLoaded", () => {
      // FAQ Toggles
      document.querySelectorAll('.nx-faq-toggle').forEach(btn => {
        btn.addEventListener('click', (e) => {
          const content = btn.nextElementSibling;
          const isHidden = content.style.display === 'none';
          // Close all others in same block optionally, but keeping simple toggle here
          content.style.display = isHidden ? 'block' : 'none';
          const icon = btn.querySelector('.nx-chevron');
          if(icon) icon.style.transform = isHidden ? 'rotate(180deg)' : 'rotate(0deg)';
        });
      });

      // Mobile Menus
      document.querySelectorAll('.nx-menu-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
          const nav = btn.parentElement.nextElementSibling;
          if(nav && nav.classList.contains('nx-mobile-menu')) {
            nav.style.display = nav.style.display === 'none' ? 'flex' : 'none';
          }
        });
      });

      // Forms
      document.querySelectorAll('.nx-form').forEach(form => {
        form.addEventListener('submit', (e) => {
          e.preventDefault();
          const btn = form.querySelector('button[type="submit"]');
          const originalText = btn.innerText;
          btn.innerText = 'Sending...';
          btn.disabled = true;
          setTimeout(() => {
            btn.innerText = 'Sent!';
            btn.style.backgroundColor = '#16a34a'; // tailwind green-600
            setTimeout(() => {
              btn.innerText = originalText;
              btn.style.backgroundColor = '';
              btn.disabled = false;
              form.reset();
            }, 3000);
          }, 1000);
        });
      });
    });
  `;

  return \`<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>\${escapeHtml(title)}</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body { margin: 0; font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; }
    .nx-chevron { transition: transform 0.2s; }
  </style>
</head>
<body class="bg-gray-900 text-white min-h-screen">
\${body}
<script>\${script}</script>
</body>
</html>\`;
}

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function sectionToHtml(section) {
  if (!section?.type) return "";
  const st = section.style || {};
  const py = Number(st.paddingY) || 0;
  const px = Number(st.paddingX) || 0;
  const maxW = Number(st.maxWidth) || 1200;

  // Convert hex background to tailwind inline style if present
  const outerStyle = [
    st.background && st.background !== 'transparent' ? \`background:\${st.background}\` : '',
    st.textColor && st.textColor !== 'inherit' ? \`color:\${st.textColor}\` : '',
    \`padding:\${py}px \${px}px\`
  ].filter(Boolean).join(";");

  const innerOpen = \`<div style="max-width:\${maxW}px;margin:0 auto">\`;
  const innerClose = \`</div>\`;

  const p = section.props || {};
  let inner = "";

  switch (section.type) {
    case "hero":
      const align = p.align === "left" ? "text-left items-start" : p.align === "right" ? "text-right items-end" : "text-center items-center";
      inner = \`<div class="flex flex-col gap-6 \${align}">
        <h1 class="text-3xl font-bold tracking-tight sm:text-4xl md:text-5xl max-w-3xl">\${escapeHtml(p.title)}</h1>
        <p class="max-w-2xl text-base opacity-90 sm:text-lg">\${escapeHtml(p.subtitle)}</p>
        <div class="flex flex-wrap gap-3">
          <button class="rounded-full bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white hover:brightness-110 transition-all">\${escapeHtml(p.primaryCta)}</button>
          <button class="rounded-full border border-white/20 px-5 py-2.5 text-sm font-medium hover:bg-white/5 transition-all">\${escapeHtml(p.secondaryCta)}</button>
        </div>
      </div>\`;
      break;

    case "navbar":
      const links = String(p.links || "").split(",").map(l => l.trim()).filter(Boolean);
      const linksHtml = links.map(l => \`<a href="#" class="hover:opacity-100 transition-opacity">\${escapeHtml(l)}</a>\`).join("");
      const stickyClass = p.sticky ? "sticky top-0 z-10 backdrop-blur-md bg-black/50" : "";

      inner = \`<header class="flex flex-wrap items-center justify-between gap-4 \${stickyClass}">
        <span class="text-lg font-semibold tracking-tight">\${escapeHtml(p.brand)}</span>
        <nav class="hidden md:flex flex-wrap items-center gap-4 text-sm opacity-90">
          \${linksHtml}
        </nav>
        <div class="hidden md:block">
          <button class="rounded-full bg-blue-600 px-4 py-2 text-xs font-semibold text-white hover:brightness-110 transition-all">\${escapeHtml(p.cta)}</button>
        </div>
        <div class="md:hidden flex items-center">
          <button class="nx-menu-btn p-2 border border-white/20 rounded">Menu</button>
        </div>
        <div class="nx-mobile-menu w-full basis-full mt-4 flex-col gap-3 hidden md:hidden">
          \${links.map(l => \`<a href="#" class="text-sm opacity-90 py-1 border-b border-white/10">\${escapeHtml(l)}</a>\`).join("")}
          <button class="w-full mt-2 rounded-full bg-blue-600 px-4 py-2 text-xs font-semibold text-white">\${escapeHtml(p.cta)}</button>
        </div>
      </header>\`;
      break;

    case "footer":
      const cols = String(p.columns || "").split(",").map(c => c.trim()).filter(Boolean);
      inner = \`<footer class="grid gap-8 sm:grid-cols-3 text-sm">
        <div>
          <div class="font-semibold">\${escapeHtml(p.brand)}</div>
          <p class="mt-2 opacity-80">\${escapeHtml(p.tagline)}</p>
        </div>
        <div class="opacity-80 flex flex-col gap-1">
          \${cols.map(c => \`<a href="#" class="hover:underline">\${escapeHtml(c)}</a>\`).join("")}
        </div>
        <div class="opacity-60">© \${new Date().getFullYear()} All rights reserved.</div>
      </footer>\`;
      break;

    case "button":
      const btnClass = p.variant === "outline" ? "border border-current hover:bg-white/5" : "bg-blue-600 text-white";
      inner = \`<div>
        <a href="\${escapeHtml(p.href || '#')}" class="inline-flex rounded-full px-5 py-2.5 text-sm font-semibold transition-all hover:brightness-110 \${btnClass}">
          \${escapeHtml(p.label)}
        </a>
      </div>\`;
      break;

    case "card":
      inner = \`<article class="overflow-hidden rounded-2xl border border-white/10 bg-white/5 shadow-lg backdrop-blur hover:bg-white/10 transition-colors">
        \${p.image ? \`<img src="\${escapeHtml(p.image)}" alt="\${escapeHtml(p.title)}" class="aspect-video w-full object-cover bg-black/20" />\` : \`<div class="aspect-video w-full bg-black/20"></div>\`}
        <div class="p-6">
          <h3 class="text-lg font-semibold">\${escapeHtml(p.title)}</h3>
          <p class="mt-2 text-sm opacity-85">\${escapeHtml(p.body)}</p>
        </div>
      </article>\`;
      break;

    case "testimonials":
      const tItems = (p.items || []).map(it => \`
        <blockquote class="rounded-2xl border border-white/10 bg-white/5 p-5 text-sm hover:border-white/20 transition-colors">
          <p class="opacity-90">"\${escapeHtml(it.quote)}"</p>
          <footer class="mt-3 text-xs opacity-70"><span class="font-semibold text-white/90">\${escapeHtml(it.author)}</span> · \${escapeHtml(it.role)}</footer>
        </blockquote>
      \`).join("");
      inner = \`<div>
        <h3 class="text-2xl font-semibold">\${escapeHtml(p.heading)}</h3>
        <div class="mt-6 grid gap-4 md:grid-cols-2">\${tItems}</div>
      </div>\`;
      break;

    case "pricing":
      const pItems = (p.plans || []).map(plan => {
        const features = String(plan.features || "").split(",").map(f => f.trim()).filter(Boolean);
        const fHtml = features.map(f => \`<li class="flex items-center gap-2"><span class="shrink-0 w-1.5 h-1.5 rounded-full bg-blue-500"></span>\${escapeHtml(f)}</li>\`).join("");
        return \`<div class="rounded-2xl border border-white/10 bg-white/5 p-6 flex flex-col shadow-sm hover:border-blue-500 transition-colors">
          <div class="text-sm font-medium opacity-80">\${escapeHtml(plan.name)}</div>
          <div class="mt-2 text-3xl font-bold">\${escapeHtml(plan.price)}</div>
          <ul class="mt-4 text-sm opacity-75 space-y-2 flex-1">\${fHtml}</ul>
          <button class="mt-6 w-full rounded-full bg-white/10 px-4 py-2 text-sm font-semibold hover:bg-white/20 transition-colors">Choose Plan</button>
        </div>\`;
      }).join("");
      inner = \`<div>
        <h3 class="text-2xl font-semibold">\${escapeHtml(p.heading)}</h3>
        <div class="mt-8 grid gap-4 md:grid-cols-3">\${pItems}</div>
      </div>\`;
      break;

    case "contact-form":
      inner = \`<div>
        <h3 class="text-2xl font-semibold">\${escapeHtml(p.heading)}</h3>
        <p class="mt-2 text-sm opacity-80">\${escapeHtml(p.subheading)}</p>
        <form class="nx-form mt-6 grid gap-3 max-w-md">
          <input required class="rounded-lg border border-white/15 bg-black/20 px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all" placeholder="Name" />
          <input required type="email" class="rounded-lg border border-white/15 bg-black/20 px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all" placeholder="Email" />
          <textarea required class="min-h-[100px] rounded-lg border border-white/15 bg-black/20 px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all" placeholder="Message"></textarea>
          <button type="submit" class="rounded-full bg-blue-600 px-4 py-2 text-sm font-semibold text-white transition-all hover:brightness-110">\${escapeHtml(p.submitLabel)}</button>
        </form>
      </div>\`;
      break;

    case "gallery":
      const colsNum = Math.min(4, Math.max(2, Number(p.columns) || 3));
      const caps = String(p.captions || "").split(",").map(c => c.trim()).filter(Boolean);
      const gItems = caps.map(c => \`<figure class="group overflow-hidden rounded-xl border border-white/10 relative cursor-pointer">
        <div class="aspect-[4/3] bg-gradient-to-br from-white/10 to-white/5 group-hover:scale-105 transition-transform duration-500"></div>
        <figcaption class="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center p-4 text-center text-sm font-medium text-white shadow-sm">\${escapeHtml(c)}</figcaption>
      </figure>\`).join("");
      inner = \`<div>
        <h3 class="text-2xl font-semibold">\${escapeHtml(p.heading)}</h3>
        <div class="mt-6 grid gap-3" style="grid-template-columns: repeat(\${colsNum}, minmax(0, 1fr))">\${gItems}</div>
      </div>\`;
      break;

    case "faq":
      const faqItems = (p.items || []).map(item => \`
        <div class="rounded-xl border border-white/10 bg-white/5 overflow-hidden transition-all">
          <dt class="nx-faq-toggle font-medium p-4 flex justify-between items-center cursor-pointer hover:bg-white/5">
            <span>\${escapeHtml(item.q)}</span>
            <svg class="nx-chevron size-4 opacity-50" style="width:16px;height:16px" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"></path></svg>
          </dt>
          <dd class="px-4 pb-4 mt-1 text-sm opacity-80 border-t border-white/5 pt-3" style="display:none;">\${escapeHtml(item.a)}</dd>
        </div>
      \`).join("");
      inner = \`<div>
        <h3 class="text-2xl font-semibold">\${escapeHtml(p.heading)}</h3>
        <dl class="mt-6 space-y-4">\${faqItems}</dl>
      </div>\`;
      break;

    default:
      inner = \`<div class="p-4 border border-dashed border-white/20 rounded-xl text-sm opacity-70">
        Unknown block type: \${escapeHtml(section.type)}
      </div>\`;
  }

  // Determine container classes based on background
  const hasBgStr = st.background && st.background.length > 0 && st.background !== 'transparent';
  return \`<section class="relative w-full" style="\${outerStyle}">\${innerOpen}\${inner}\${innerClose}</section>\`;
}
